<script setup>import {onMounted,ref} from 'vue';import {del,get,post} from '../api/client';const props=defineProps({user:Object}),sessions=ref([]),current=ref(''),next=ref(''),confirm=ref(''),message=ref('');async function load(){sessions.value=await get('/auth/sessions')}async function change(){if(next.value!==confirm.value){message.value='两次新密码不一致';return}try{await post('/auth/change-password',{current_password:current.value,new_password:next.value});message.value='密码修改成功，其他设备已退出';current.value=next.value=confirm.value='';await load()}catch(e){message.value=e.message}}async function revoke(row){await del(`/auth/sessions/${row.id}`);await load()}onMounted(load)</script><template><div class="profile-grid"><section class="card"><h2>个人资料</h2><p><b>{{user.display_name}}</b> · {{user.username}}</p><p>{{user.email||'未设置邮箱'}} · {{user.mobile||'未设置手机'}}</p><p class="hint">角色：{{user.roles.map(r=>r.role_name).join('、')}}</p></section><form class="card" @submit.prevent="change"><h2>修改密码</h2><label>当前密码<input v-model="current" type="password"></label><label>新密码<input v-model="next" type="password"></label><label>确认密码<input v-model="confirm" type="password"></label><p v-if="message" class="notice">{{message}}</p><button class="primary-button">修改密码</button></form></div><div class="section"><h2>我的登录设备</h2><div class="device-list"><article v-for="row in sessions" class="card"><b>{{row.current?'当前设备':'其他设备'}}</b><span>{{row.ip_address||'未知IP'}}</span><small>{{row.user_agent}}</small><small>最后活动：{{row.last_active_at}}</small><button v-if="!row.current&&!row.revoked_at" @click="revoke(row)">退出该设备</button><span v-if="row.revoked_at">已退出</span></article></div></div></template>
